const out = {};
// workspace page
const ws = figma.root.children.find(p=>p.name.includes('03 · Workspace'));
out.workspace = ws ? {id: ws.id, name: ws.name, children: ws.children.map(c=>({id:c.id,name:c.name,type:c.type}))} : null;
// Button & Text Field
function dump(n, depth){
  const o = {id:n.id,name:n.name,type:n.type};
  if('width' in n){o.w=Math.round(n.width);o.h=Math.round(n.height);}
  if(n.fills && n.fills!==figma.mixed) o.fills=JSON.parse(JSON.stringify(n.fills));
  if(n.cornerRadius!==undefined && n.cornerRadius!==figma.mixed) o.radius=n.cornerRadius;
  if(n.strokes) o.strokes=JSON.parse(JSON.stringify(n.strokes));
  if(n.strokeWeight!==undefined&&n.strokeWeight!==figma.mixed) o.sw=n.strokeWeight;
  if(n.type==='TEXT'){o.chars=n.characters;o.fontName=n.fontName;o.fontSize=n.fontSize;o.color=JSON.parse(JSON.stringify(n.fills));}
  if(n.layoutMode) {o.layoutMode=n.layoutMode;o.itemSpacing=n.itemSpacing;o.padding=[n.paddingTop,n.paddingRight,n.paddingBottom,n.paddingLeft];o.primaryAlign=n.primaryAxisAlignItems;o.counterAlign=n.counterAxisAlignItems;}
  if('children' in n && depth>0) o.children=n.children.map(c=>dump(c,depth-1));
  return o;
}
